"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/how-it-works/variants/01-centered-cards";
import View1 from "./components/how-it-works/variants/02-process-grid";
import View2 from "./components/how-it-works/variants/03-story-stack";
import View3 from "./components/how-it-works/variants/04-walkthrough";
import View4 from "./components/how-it-works/variants/05-card-deck";
const variants = {"centered-cards":View0,"process-grid":View1,"story-stack":View2,"walkthrough":View3,"card-deck":View4};
export interface ArtemisHowItWorksProps { className?: string; variant?: "centered-cards" | "process-grid" | "story-stack" | "walkthrough" | "card-deck"; }
export function ArtemisHowItWorks({ className, variant = "centered-cards" }: ArtemisHowItWorksProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}
